    print('FILE:',path,'EXT:',f.split('.')[-1])
    if f.endswith('.db'):
      con=sqlite3.connect(path)
      for t in con.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall():
        cols=con.execute(f"PRAGMA table_info({t[0]})").fetchall()
